// Browser-side half of the admin Performance page: measures what a viewer on
// this machine experiences — API round-trip time, download bandwidth, and
// Deep Zoom tile fetches through nginx — and returns a result the page posts
// back to /api/admin/perf/client-runs for the history.
//
// Two tile modes:
//   * 'app'   — requests carry the admin Bearer token. nginx neither serves
//               nor stores those from its tile cache (proxy_cache_bypass /
//               proxy_no_cache on $http_authorization), so every tile is
//               generated by the app: the cache-miss path, without polluting
//               the shared cache. The token also bypasses nginx's cached
//               access verdict, so each tile costs one extra /api/edge-authz
//               round trip a viewer's cache miss doesn't pay: a slightly
//               pessimistic figure. The tile sample is fresh on every run —
//               re-fetching the same tiles would be served from the OS page
//               cache and OpenSlide's tile cache and look faster each time.
//   * 'cache' — plain requests, exactly what a viewer's browser sends: an
//               nginx HIT when the tile is cached, otherwise generated and
//               cached (so this mode also pre-warms the tiles it touched). The
//               X-Cache-Status response header says which happened. The
//               sample is fixed per slide, so a second run shows how much the
//               cache now answers.
//
// Both modes request the same URLs a viewer does, including the slide's
// `?v=` tile generation (lib/tileUrl): nginx keys the tile cache on it and
// never stores an unversioned tile, so without it 'cache' mode could neither
// hit nor warm the entries viewers use.
import {
  ApiCodeError,
  adminPerfDownload,
  adminPerfPing,
  authHeaders,
  type PerfClientBand,
  type PerfClientConditions,
  type PerfClientResult,
  type PerfStats,
  type Slide,
} from '../api'
import { dziDescriptorUrl, dziTileUrl } from '../tileUrl'

export type ClientTestMode = 'app' | 'cache'

export type ClientTestParams = {
  slide: Slide
  mode: ClientTestMode
  tiles: number
  concurrency: number
}

export type ClientTestProgress = {
  phase: 'rtt' | 'download' | 'tiles'
  done: number
  total: number
}

// Browsers open at most 6 connections to one host over HTTP/1.1 (nginx
// serves HTTP/1.1), so more parallel fetches would only queue inside the
// browser and that wait would be counted as tile latency.
export const MAX_CLIENT_CONCURRENCY = 6

// The timing method a result is measured with (summary.timing; see
// PerfSummary.timing). This code always times the download from its body
// alone (response headers to last byte), so any run carrying the marker has a
// download speed without the round trip; a run without the marker timed it
// with fetch() around the request, round trip included. What
// the marker's value says is how the tile times were taken:
//   2  every tile that succeeded was timed by Resource Timing (the request's
//      own timeline, from when it left the browser);
//   1  some or all were not — no PerformanceObserver, a cross-origin entry
//      whose detail the browser zeroed, an entry dropped or doubled — and
//      kept the fetch() figure, which includes the wait for one of the
//      browser's connections, as the tile times of unmarked runs do.
// The claim is all-or-nothing on purpose: the percentiles mix every tile, so a
// share timed by fetch() makes them neither one method's nor the other's. The
// exact split is in the result (tiles.timing). Bump the values whenever a change
// makes new figures not directly comparable with stored ones.
export const CLIENT_TIMING_RESOURCE = 2
export const CLIENT_TIMING_FETCH = 1

const SAMPLE_COLUMNS = ['start_ms', 'band', 'level', 'col', 'row', 'ttfb_ms', 'total_ms', 'bytes', 'cache', 'ok', 'protocol']

const PING_COUNT = 10
const MIB = 1024 * 1024
const DOWNLOAD_TARGET_SECONDS = 1.5
const DOWNLOAD_MAX_BYTES = 32 * MIB
// The download probes, tried in turn until one gives a usable reading (see
// measureNetwork), and the shortest body time that is one.
const PROBE_BYTES = [MIB, 8 * MIB]
const MIN_BODY_SECONDS = 1e-3
const BANDS: Array<{ band: PerfClientBand['band']; drop: number }> = [
  { band: 'high', drop: 0 },
  { band: 'mid', drop: 2 },
  { band: 'low', drop: 4 },
]

// Python's round(x, 2): the double nearest the exactly-rounded decimal, a
// tie going to the even hundredth. Math.round(x * 100) / 100 differs twice:
// x * 100 is itself rounded (1.005 * 100 = 100.49999…), and an exact tie
// goes up (0.125 → 0.13 where Python says 0.12). toFixed rounds the exact
// value of the double, and a double can only sit exactly on a tie when it is
// an odd multiple of 1/8 (k / 200 is a binary fraction only when 25 | k), so
// that case alone is settled here.
export function round2(x: number): number {
  if (!Number.isFinite(x)) return x
  const eighths = x * 8
  if (Number.isInteger(eighths) && eighths % 2 !== 0) {
    const lo = Math.floor(x * 100)
    return (lo % 2 === 0 ? lo : lo + 1) / 100
  }
  return Number(x.toFixed(2))
}

// Python's sum() of floats (3.12+): Neumaier-compensated, so a long run of
// samples does not drift from the server's mean in the last digit.
function pySum(values: number[]): number {
  let sum = 0
  let c = 0
  for (const x of values) {
    const t = sum + x
    c += Math.abs(sum) >= Math.abs(x) ? (sum - t) + x : (x - t) + sum
    sum = t
  }
  return c && Number.isFinite(c) ? sum + c : sum
}

// Same summary as perf_bench.stats_ms on the server (linear-interpolated
// percentiles, its rounding and its summation), so client and server numbers
// are read the same way; perfClientTest.test.ts pins both to one fixture.
export function perfStats(values: number[]): PerfStats {
  if (!values.length) return { count: 0 }
  const arr = [...values].sort((a, b) => a - b)
  const n = arr.length
  const pct = (p: number) => {
    const k = (n - 1) * p / 100
    const lo = Math.floor(k)
    const hi = Math.min(lo + 1, n - 1)
    return arr[lo] + (arr[hi] - arr[lo]) * (k - lo)
  }
  const r2 = round2
  return {
    count: n,
    mean: r2(pySum(arr) / n),
    min: r2(arr[0]),
    p50: r2(pct(50)),
    p90: r2(pct(90)),
    p95: r2(pct(95)),
    p99: r2(pct(99)),
    max: r2(arr[n - 1]),
  }
}

// Small deterministic PRNG (mulberry32) for a reproducible tile sample.
function mulberry32(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export type Descriptor = { width: number; height: number; tileSize: number; overlap: number; format: string }

// A malformed descriptor is a typed error with its own message: the raw
// parser text would reach the admin untranslated.
function parseDescriptor(xml: string): Descriptor {
  const doc = new DOMParser().parseFromString(xml, 'application/xml')
  const image = doc.getElementsByTagNameNS('*', 'Image')[0]
  const size = doc.getElementsByTagNameNS('*', 'Size')[0]
  if (!image || !size) throw new ApiCodeError('adminPerf.client.err.badDescriptor')
  const width = Number(size.getAttribute('Width'))
  const height = Number(size.getAttribute('Height'))
  const tileSize = Number(image.getAttribute('TileSize'))
  const overlap = Number(image.getAttribute('Overlap') || 0)
  const format = image.getAttribute('Format') || 'jpeg'
  if (!(width > 0 && height > 0 && tileSize > 0)) throw new ApiCodeError('adminPerf.client.err.badDescriptor')
  return { width, height, tileSize, overlap, format }
}

// Deep Zoom's top level: the one at full resolution.
function maxLevelOf(d: Descriptor): number {
  return Math.ceil(Math.log2(Math.max(d.width, d.height)))
}

export type TileJob = { band: PerfClientBand['band']; level: number; col: number; row: number; url: string }

type NavigatorExtras = Navigator & {
  connection?: { effectiveType?: string; downlink?: number; rtt?: number; saveData?: boolean; type?: string }
  deviceMemory?: number
  userAgentData?: { platform?: string; mobile?: boolean }
}

// What this browser, device and network look like right now: everything about
// the measuring side that changes what the numbers mean. Read from whatever
// the browser exposes (Chromium reports more than Safari / Firefox); a value
// it hides is null, never a guess.
export function collectClientConditions(): Omit<PerfClientConditions, 'started_at' | 'finished_at' | 'duration_s' | 'http_protocols' | 'hidden_during_run'> {
  const nav = navigator as NavigatorExtras
  const conn = nav.connection
  let timezone: string | null = null
  try { timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || null } catch {}
  return {
    user_agent: nav.userAgent,
    platform: nav.userAgentData?.platform || nav.platform || null,
    mobile: typeof nav.userAgentData?.mobile === 'boolean' ? nav.userAgentData.mobile : null,
    language: nav.language || null,
    timezone,
    hardware_concurrency: nav.hardwareConcurrency || null,
    device_memory_gb: typeof nav.deviceMemory === 'number' ? nav.deviceMemory : null,
    device_pixel_ratio: window.devicePixelRatio || 1,
    viewport: { width: window.innerWidth, height: window.innerHeight },
    screen: { width: window.screen?.width ?? 0, height: window.screen?.height ?? 0 },
    max_touch_points: typeof nav.maxTouchPoints === 'number' ? nav.maxTouchPoints : null,
    connection_type: conn?.type ?? null,
    effective_type: conn?.effectiveType ?? null,
    downlink_mbps: conn?.downlink ?? null,
    connection_rtt_ms: conn?.rtt ?? null,
    save_data: typeof conn?.saveData === 'boolean' ? conn.saveData : null,
    page_origin: window.location.origin,
    secure_context: !!window.isSecureContext,
  }
}

// What Resource Timing says about each tile response: the protocol the
// browser negotiated (h2, http/1.1, h3) and the request's own timeline.
// Entries are collected by an observer for the length of the tile phase
// rather than looked up in the performance buffer afterwards: that buffer
// keeps 250 entries by default and records nothing once full — a long run,
// or any later run in the same tab — so later tiles would silently go
// missing. Only entries that start inside the phase count, so a straggler
// from an earlier run of the same URLs ('cache' mode reuses its sample) is
// never matched.
type ResourceTimes = { ttfb: number; total: number }

function watchResources(phaseStart: number): {
  protocolOf: (url: string) => string
  timesOf: (url: string) => ResourceTimes | null
  stop: () => Promise<void>
} {
  const seen = new Map<string, PerformanceResourceTiming[]>()
  const record = (entries: PerformanceEntryList) => {
    for (const e of entries as PerformanceResourceTiming[]) {
      if (typeof e.startTime === 'number' && e.startTime < phaseStart) continue
      const list = seen.get(e.name)
      if (list) list.push(e)
      else seen.set(e.name, [e])
    }
  }
  const entriesOf = (url: string): PerformanceResourceTiming[] => {
    try {
      return seen.get(new URL(url, window.location.href).href) ?? []
    } catch {
      return []
    }
  }
  let observer: PerformanceObserver | null = null
  try {
    observer = new PerformanceObserver((list) => record(list.getEntries()))
    observer.observe({ type: 'resource' })
  } catch {
    observer = null
  }
  return {
    // '' for a URL with no entry (a browser that doesn't support the
    // observer, or leaves the field empty).
    protocolOf: (url) => {
      const list = entriesOf(url)
      return list[list.length - 1]?.nextHopProtocol || ''
    },
    // From the moment the request left the browser (requestStart), so the
    // time a fetch spent queued for a free connection inside the browser —
    // or setting one up — is not counted as the server's latency. null
    // unless exactly one plausible entry belongs to the URL (none: the
    // browser hides the timeline or dropped the entry; several: the same
    // tile twice in one run, which could not be told apart); the caller then
    // keeps its own fetch() timing.
    timesOf: (url) => {
      const list = entriesOf(url)
      if (list.length !== 1) return null
      const { requestStart: rq, responseStart: rs, responseEnd: re } = list[0]
      if (!(rq > 0 && rs >= rq && re >= rs)) return null
      return { ttfb: rs - rq, total: re - rq }
    },
    stop: async () => {
      if (!observer) return
      // A response's entry can be queued just after its body resolves: give
      // the last ones a moment, then take what is still pending.
      await new Promise((resolve) => setTimeout(resolve, 50))
      record(observer.takeRecords())
      observer.disconnect()
    },
  }
}

// The tile sample: `total` tiles split over the three zoom bands (the
// remainder going to full resolution), each band drawn without repeats from
// its level's grid — or the whole grid when it has fewer tiles than asked.
// On a slide small enough that two bands clamp to level 0 they draw from the
// same grid, so a tile can then appear in both.
export function sampleTiles(
  publicId: string,
  d: Descriptor,
  total: number,
  seed: number,
  tileVersion: number | null | undefined,
): TileJob[] {
  const rnd = mulberry32(seed)
  const maxLevel = maxLevelOf(d)
  const per = Math.floor(total / BANDS.length)
  const jobs: TileJob[] = []
  BANDS.forEach(({ band, drop }, i) => {
    const want = per + (i === 0 ? total - per * BANDS.length : 0)
    const level = Math.max(0, maxLevel - drop)
    const scale = 2 ** (maxLevel - level)
    const cols = Math.ceil(Math.ceil(d.width / scale) / d.tileSize)
    const rows = Math.ceil(Math.ceil(d.height / scale) / d.tileSize)
    const seen = new Set<string>()
    for (let tries = 0; seen.size < Math.min(want, cols * rows) && tries < want * 20; tries++) {
      const col = Math.floor(rnd() * cols)
      const row = Math.floor(rnd() * rows)
      const key = `${col}_${row}`
      if (seen.has(key)) continue
      seen.add(key)
      jobs.push({
        band,
        level,
        col,
        row,
        url: dziTileUrl(publicId, level, col, row, d.format, tileVersion),
      })
    }
  })
  return jobs
}

async function measureNetwork(
  signal: AbortSignal | undefined,
  onProgress: (p: ClientTestProgress) => void,
): Promise<PerfClientResult['network']> {
  const rtts: number[] = []
  for (let i = 0; i < PING_COUNT; i++) {
    rtts.push(await adminPerfPing(signal))
    onProgress({ phase: 'rtt', done: i + 1, total: PING_COUNT })
  }
  // A 1 MiB probe sizes the real measurement so it lasts about
  // DOWNLOAD_TARGET_SECONDS whatever the link speed; the best of two runs of
  // that size is reported. adminPerfDownload times the body only (response
  // headers to last byte): with the round trip and the server's first byte
  // in it, a 1 MiB probe on a fast link would read as a fraction of the real rate
  // and size the measurement far below its target.
  //
  // A body timed under MIN_BODY_SECONDS is no reading at all: the browser had
  // it buffered before the timer started (or stamps a coarse clock), so the
  // fetch() fallback reads ~0 s just as a zeroed Resource Timing span does.
  // Taken at face value it would be an absurd Mbps figure — and, on the probe,
  // a rate (floored at 1 ms) that would size the measurement to its 32 MiB cap. Such
  // a reading is kept in `downloads` with no Mbps, counts towards no figure,
  // and a probe that gives one is repeated with a larger body, whose transfer
  // the timer can resolve.
  const downloads: PerfClientResult['network']['downloads'] = []
  const record = (bytes: number, seconds: number): number | null => {
    const usable = bytes > 0 && seconds >= MIN_BODY_SECONDS
    const mbps = usable ? Math.round((bytes * 8) / seconds / 1e6 * 10) / 10 : null
    downloads.push({ bytes, seconds: Math.round(seconds * 1000) / 1000, mbps })
    return usable ? bytes / seconds : null
  }
  onProgress({ phase: 'download', done: 0, total: 3 })
  let rate: number | null = null
  for (const probeSize of PROBE_BYTES) {
    const probe = await adminPerfDownload(probeSize, signal)
    rate = record(probe.bytes, probe.seconds)
    if (rate != null) break
  }
  const probes = downloads.length
  // No probe gave a reading: nothing is known of the rate but that it is
  // beyond what the probes could time, so the measurement takes the largest
  // body allowed — the best chance of one long enough to time.
  const size = rate == null
    ? DOWNLOAD_MAX_BYTES
    : Math.min(DOWNLOAD_MAX_BYTES, Math.max(MIB, Math.round(rate * DOWNLOAD_TARGET_SECONDS)))
  for (let i = 1; i <= 2; i++) {
    onProgress({ phase: 'download', done: i, total: 3 })
    const d = await adminPerfDownload(size, signal)
    record(d.bytes, d.seconds)
  }
  onProgress({ phase: 'download', done: 3, total: 3 })
  const sized = downloads.slice(probes).flatMap((d) => (d.mbps == null ? [] : [d.mbps]))
  return {
    rtt_ms: perfStats(rtts),
    downloads,
    mbps: sized.length ? Math.max(...sized) : null,
  }
}

// Browsers throttle a background tab, so a run during which the tab was
// hidden even once does not measure the network or the server.
function watchVisibility(): { wasHidden: () => boolean; stop: () => void } {
  let hidden = document.visibilityState === 'hidden'
  const onChange = () => { if (document.visibilityState === 'hidden') hidden = true }
  document.addEventListener('visibilitychange', onChange)
  return { wasHidden: () => hidden, stop: () => document.removeEventListener('visibilitychange', onChange) }
}

export async function runClientTest(
  params: ClientTestParams,
  onProgress: (p: ClientTestProgress) => void,
  signal?: AbortSignal,
): Promise<PerfClientResult> {
  const visibility = watchVisibility()
  try {
    return await measureClient(params, onProgress, signal, visibility.wasHidden)
  } finally {
    visibility.stop()
  }
}

async function measureClient(
  params: ClientTestParams,
  onProgress: (p: ClientTestProgress) => void,
  signal: AbortSignal | undefined,
  wasHidden: () => boolean,
): Promise<PerfClientResult> {
  const { slide, mode, tiles } = params
  const concurrency = Math.max(1, Math.min(MAX_CLIENT_CONCURRENCY, params.concurrency))
  const startedAt = new Date()
  const conditions = collectClientConditions()

  // The descriptor comes first so a slide the tile path can't serve fails
  // before the network phase has been spent.
  const headers = mode === 'app' ? authHeaders() : {}
  const dziRes = await fetch(dziDescriptorUrl(slide.public_id, slide.tile_version), { headers, cache: 'no-store', signal })
  if (!dziRes.ok) {
    // Without the token, nginx's access gate wants the viewer's own session
    // cookie, which signing in to the admin dashboard alone doesn't set.
    if (mode === 'cache' && (dziRes.status === 401 || dziRes.status === 403)) {
      throw new ApiCodeError('adminPerf.client.err.viewerLogin')
    }
    throw new ApiCodeError('adminPerf.client.err.descriptor', { status: dziRes.status })
  }
  const descriptor = parseDescriptor(await dziRes.text())
  const seed = mode === 'cache' ? slide.id : crypto.getRandomValues(new Uint32Array(1))[0]
  const jobs = sampleTiles(slide.public_id, descriptor, tiles, seed, slide.tile_version)

  const network = await measureNetwork(signal, onProgress)

  // status 0: the request got no HTTP answer at all (network failure).
  type Sample = {
    job: TileJob; start: number; ttfb: number; total: number; bytes: number; cache: string; ok: boolean; status: number
  }
  const samples: Sample[] = []
  let next = 0
  let done = 0
  const started = performance.now()
  const resources = watchResources(started)
  onProgress({ phase: 'tiles', done: 0, total: jobs.length })
  const worker = async () => {
    while (next < jobs.length) {
      const job = jobs[next++]
      const t0 = performance.now()
      try {
        // no-store: the browser must neither answer from its own cache nor
        // send If-None-Match (a 304 would measure revalidation, not a tile).
        const r = await fetch(job.url, { headers, cache: 'no-store', signal })
        const t1 = performance.now()
        const buf = await r.arrayBuffer()
        const t2 = performance.now()
        samples.push({
          job,
          start: t0 - started,
          ttfb: t1 - t0,
          total: t2 - t0,
          bytes: buf.byteLength,
          cache: (r.headers.get('X-Cache-Status') || 'none').toUpperCase(),
          ok: r.ok,
          status: r.status,
        })
      } catch (err) {
        if ((err as Error)?.name === 'AbortError') throw err
        samples.push({ job, start: t0 - started, ttfb: 0, total: 0, bytes: 0, cache: 'none', ok: false, status: 0 })
      }
      done += 1
      onProgress({ phase: 'tiles', done, total: jobs.length })
    }
  }
  let wall: number
  try {
    await Promise.all(Array.from({ length: Math.max(1, Math.min(concurrency, jobs.length)) }, worker))
  } finally {
    wall = (performance.now() - started) / 1000
    await resources.stop()
  }
  const protocolOf = (s: Sample) => (s.ok ? resources.protocolOf(s.job.url) : '')
  // The fetch() timings above count from when the request was issued, so a
  // tile waiting for one of the browser's connections reads as slow server.
  // Wherever Resource Timing has the request's own timeline, that replaces
  // them; the rest keep the fetch() figure, and the split is recorded.
  const timing = { resource: 0, fetch: 0 }
  const resourceTimed = new Set<Sample>()
  for (const s of samples) {
    if (!s.status) continue
    const rt = resources.timesOf(s.job.url)
    if (rt) {
      s.ttfb = rt.ttfb
      s.total = rt.total
      timing.resource += 1
      resourceTimed.add(s)
    } else {
      timing.fetch += 1
    }
  }

  const ok = samples.filter((s) => s.ok)
  // The figures below are the OK tiles' alone, so the method they claim is
  // too (see CLIENT_TIMING_RESOURCE).
  const tileTiming = ok.length > 0 && ok.every((s) => resourceTimed.has(s))
    ? CLIENT_TIMING_RESOURCE
    : CLIENT_TIMING_FETCH
  // Failed tiles stay out of every figure below (a fast 404 or 500 would
  // flatter them); their count goes into the summary, so the history and the
  // comparison can flag the run, and the time to an HTTP error is reported
  // on its own (a network failure has none to report).
  const failed = samples.filter((s) => !s.ok)
  const errorMs = perfStats(failed.filter((s) => s.status > 0).map((s) => s.total))
  const bytes = ok.reduce((s, x) => s + x.bytes, 0)
  const cache: Record<string, number> = {}
  const ttfbByCache: Record<string, number[]> = {}
  for (const s of ok) {
    cache[s.cache] = (cache[s.cache] || 0) + 1
    ;(ttfbByCache[s.cache] ||= []).push(s.ttfb)
  }
  const byBand: PerfClientBand[] = BANDS.map(({ band }) => {
    const rows = ok.filter((s) => s.job.band === band)
    return {
      band,
      level: rows[0]?.job.level ?? jobs.find((j) => j.band === band)?.level ?? 0,
      count: rows.length,
      ttfb_ms: perfStats(rows.map((s) => s.ttfb)),
      total_ms: perfStats(rows.map((s) => s.total)),
    }
  })
  const ttfb = perfStats(ok.map((s) => s.ttfb))
  // Only meaningful behind nginx: without an X-Cache-Status header at all
  // (dev server, or a proxy that strips it) the hit rate is unknown, not 0%.
  const withHeader = ok.filter((s) => s.cache !== 'NONE')
  const cacheHitPct = mode === 'cache' && withHeader.length
    ? Math.round(((cache.HIT || 0) / withHeader.length) * 1000) / 10
    : null
  const tilesPerSec = wall > 0 ? Math.round((ok.length / wall) * 10) / 10 : null
  // Tiles whose protocol the browser didn't report count as "unknown", so
  // the counts always add up to the tiles that succeeded.
  const httpProtocols: Record<string, number> = {}
  for (const s of ok) {
    const p = protocolOf(s) || 'unknown'
    httpProtocols[p] = (httpProtocols[p] || 0) + 1
  }
  const finishedAt = new Date()
  const r2 = round2
  const hidden = wasHidden()
  return {
    schema: 1,
    params: { slide_id: slide.id, slide_title: slide.title || slide.catalog_id || slide.wsi_filename, mode, tiles, concurrency, seed },
    slide: {
      id: slide.id,
      public_id: slide.public_id,
      width: descriptor.width,
      height: descriptor.height,
      tile_size: descriptor.tileSize,
      overlap: descriptor.overlap,
      tile_format: descriptor.format,
      max_level: maxLevelOf(descriptor),
      tile_version: slide.tile_version ?? null,
      published: !!slide.is_published,
    },
    network,
    tiles: {
      requested: jobs.length,
      ok: ok.length,
      errors: failed.length,
      wall_s: Math.round(wall * 100) / 100,
      tiles_per_s: tilesPerSec,
      mb_per_s: wall > 0 ? Math.round((bytes / wall / 1e6) * 100) / 100 : null,
      ttfb_ms: ttfb,
      total_ms: perfStats(ok.map((s) => s.total)),
      by_band: byBand,
      cache,
      ttfb_by_cache: Object.fromEntries(Object.entries(ttfbByCache).map(([k, v]) => [k, perfStats(v)])),
      error_ms: errorMs,
      timing,
      // Every request in issue order: the distribution and its outliers,
      // not just the percentiles above. start_ms counts from the start of
      // the tile phase, which follows the round-trip and download probes.
      samples: {
        columns: SAMPLE_COLUMNS,
        rows: [...samples].sort((a, b) => a.start - b.start).map((s) => [
          r2(s.start), s.job.band, s.job.level, s.job.col, s.job.row,
          r2(s.ttfb), r2(s.total), s.bytes, s.cache, s.ok, protocolOf(s),
        ]),
      },
    },
    client: {
      ...conditions,
      started_at: startedAt.toISOString(),
      finished_at: finishedAt.toISOString(),
      duration_s: Math.round((finishedAt.getTime() - startedAt.getTime()) / 100) / 10,
      http_protocols: httpProtocols,
      hidden_during_run: hidden,
    },
    // The history list shows only the summary, so what makes a run's
    // numbers questionable is repeated here (the server copies it to the
    // run's summary as is).
    summary: {
      rtt_ms: network.rtt_ms.p50 ?? null,
      mbps: network.mbps,
      tiles_per_s: tilesPerSec,
      tile_ttfb_p95_ms: ttfb.p95 ?? null,
      cache_hit_pct: cacheHitPct,
      tile_errors: failed.length,
      hidden_during_run: hidden,
      // How these were timed (see PerfSummary.timing): runs saved without it
      // carry none, and the comparison says when two runs differ in it.
      timing: tileTiming,
    },
  }
}
